package com.tehang.enterpriserisk.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.tehang.enterpriserisk.api.RiskController.Factor; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RiskService {
  @Transactional public Map<String,Object> updateIdentity(long id,String name,String code,String type){return updateIdentity(id,name,code,type,db.queryForObject("select sales_manager from er_enterprise_profile where id=?",String.class,id));}
  public static final List<String> CAPS=List.of("COMPANY_REGISTRATION","EQUITY_TREE","RISK_OVERVIEW","DISHONEST","JUDGMENT_DEBTOR","JUDICIAL_CASE","CASE_FILING","SHELL_COMPANY","BIDDING","FINANCING","CREDIT_EVALUATION"); static final Set<String> FACTORS=Set.of("DISHONEST","JUDGMENT_DEBTOR","JUDICIAL_CASE","CASE_FILING","SHELL_COMPANY"); private final JdbcTemplate db;private final KeyService keys;private final TianyanchaClient client;public RiskService(JdbcTemplate d,KeyService k,TianyanchaClient c){db=d;keys=k;client=c;}
  public List<Map<String,Object>> list(String name,String code,String sales,String batch,String level,String status,String successStart,String successEnd){StringBuilder q=new StringBuilder("select id,company_name \"companyName\",unified_credit_code \"unifiedCreditCode\",sales_manager \"salesManager\",latest_collection_batch_no \"latestCollectionBatchNo\",subject_type \"subjectType\",source,monitoring_enabled \"monitoringEnabled\",collection_status \"collectionStatus\",latest_success_at \"latestSuccessAt\",risk_score \"riskScore\",risk_level \"riskLevel\",coverage from er_enterprise_profile where deleted=false");List<Object> p=new ArrayList<>();like(q,p,"company_name",name);like(q,p,"unified_credit_code",code);like(q,p,"sales_manager",sales);like(q,p,"latest_collection_batch_no",batch);riskLevelFilter(q,p,level);equals(q,p,"collection_status",status);instant(q,p,"latest_success_at>=?",successStart);instant(q,p,"latest_success_at<?",successEnd);return db.queryForList(q.append(" order by id desc").toString(),p.toArray());}private void like(StringBuilder q,List<Object>p,String col,String v){if(v!=null&&!v.isBlank()){q.append(" and ").append(col).append(" like ?");p.add("%"+v.trim()+"%");}}private void equals(StringBuilder q,List<Object>p,String col,String v){if(v!=null&&!v.isBlank()){q.append(" and ").append(col).append("=?");p.add(v.trim());}}private void riskLevelFilter(StringBuilder q,List<Object>p,String v){if(v!=null&&!v.isBlank()){q.append(" and (risk_level=? or risk_level like ?)");p.add(v.trim());p.add(v.trim()+"*%");}}private void instant(StringBuilder q,List<Object>p,String condition,String value){if(value==null||value.isBlank())return;try{q.append(" and ").append(condition);p.add(Instant.parse(value));}catch(Exception e){throw new IllegalArgumentException("最近成功时间格式无效");}}
  public byte[] exportCsv(String name,String code,String sales,String batch,String level,String status,String successStart,String successEnd){
    List<Map<String,Object>> rows=list(name,code,sales,batch,level,status,successStart,successEnd);
    StringBuilder out=new StringBuilder("\uFEFF企业名称,统一社会信用代码,销售经理,风险等级,采集状态,采集批次号,采集时间,风险说明\r\n");
    for(Map<String,Object> row:rows){
      String explanation="无命中风险因素";
      try{
Map<String,Object> score=db.queryForObject("select evidence_json evidenceJson from er_risk_score where profile_id=? order by scored_at desc limit 1",(rs,n)->rs.next()?parseEvidence(rs.getString("evidenceJson")):null,row.get("id"));
        if(score!=null&&score.get("factors") instanceof List<?> factors){List<String> hits=new ArrayList<>();for(Object item:factors)if(item instanceof Map<?,?> f&&"TRIGGERED".equals(String.valueOf(f.get("result")))){Object countValue=f.get("recordCount");String count=String.valueOf(countValue==null?0:countValue);hits.add(String.valueOf(f.get("factorName"))+"（"+levelName(String.valueOf(f.get("riskLevel")))+"，"+count+"条）");}if(!hits.isEmpty())explanation=String.join("、",hits);}
      }catch(Exception ignored){}
      out.append(csv(row.get("companyName"))).append(',').append(csv(row.get("unifiedCreditCode"))).append(',').append(csv(row.get("salesManager"))).append(',').append(csv(levelName(String.valueOf(row.get("riskLevel"))))).append(',').append(csv(statusName(String.valueOf(row.get("collectionStatus"))))).append(',').append(csv(row.get("latestCollectionBatchNo"))).append(',').append(csv(row.get("latestSuccessAt"))).append(',').append(csv(explanation)).append("\r\n");
    }
    return out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
  }
  private String csv(Object value){String s=value==null?"":String.valueOf(value);return "\""+s.replace("\"","\"\"")+"\"";}
  private String levelName(String level){String[] parts=String.valueOf(level).split("\\*",2);String base=switch(parts[0]){case "CRITICAL"->"严重风险";case "HIGH"->"高风险";case "MEDIUM"->"中风险";case "LOW"->"低风险";case "NONE","null",""->"无风险";default->parts[0];};return parts.length>1?base+"*"+parts[1]:base;}
  private String statusName(String status){return switch(status){case "SUCCEEDED"->"采集成功";case "PARTIAL"->"部分成功";case "FAILED"->"采集失败";case "COLLECTING"->"采集中";case "UNSCANNED"->"未采集";case "PENDING_QUOTA"->"等待配额";default->status;};}
  public boolean isDeletedCode(String code){return db.queryForObject("select count(*) from er_enterprise_profile where unified_credit_code=? and deleted=true",Integer.class,code.trim().toUpperCase(Locale.ROOT))>0;}
  @Transactional public Map<String,Object> updateIdentity(long id,String name,String code,String type,String sales){if(name==null||name.isBlank())throw new IllegalArgumentException("企业名称不能为空");if(sales==null||sales.isBlank())throw new IllegalArgumentException("销售经理不能为空");String c=code==null?"":code.trim().toUpperCase(Locale.ROOT);if(c.length()!=18)throw new IllegalArgumentException("统一社会信用代码必须为18位");if(!Set.of("ENTERPRISE","GOVERNMENT","OTHER").contains(type))throw new IllegalArgumentException("主体类型无效");if(db.queryForObject("select count(*) from er_enterprise_profile where unified_credit_code=? and id<>?",Integer.class,c,id)>0)throw new IllegalArgumentException("统一社会信用代码已存在");int changed=db.update("update er_enterprise_profile set company_name=?,unified_credit_code=?,subject_type=?,sales_manager=?,updated_at=? where id=? and deleted=false",name.trim(),c,type,sales.trim(),Instant.now(),id);if(changed==0)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");return db.queryForMap("select id,company_name companyName,unified_credit_code unifiedCreditCode,subject_type subjectType,sales_manager salesManager from er_enterprise_profile where id=?",id);}
  @Transactional public void updateSalesManager(long id,String sales){if(sales==null||sales.isBlank())throw new IllegalArgumentException("销售经理不能为空");if(db.update("update er_enterprise_profile set sales_manager=?,updated_at=? where id=? and deleted=false",sales.trim(),Instant.now(),id)==0)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");}
  @Transactional public Map<String,Object> upsert(String code,String name,String type,Boolean enabled,String source,String sales){return upsert(code,name,type,enabled,source,sales,false);}
  @Transactional public Map<String,Object> upsert(String code,String name,String type,Boolean enabled,String source,String sales,boolean reactivate){if(sales==null||sales.isBlank())throw new IllegalArgumentException("销售经理不能为空");String c=code.trim().toUpperCase(Locale.ROOT);Instant n=Instant.now();int exists=db.queryForObject("select count(*) from er_enterprise_profile where unified_credit_code=?",Integer.class,c);if(exists>0){boolean deleted=isDeletedCode(c);if(deleted&&!reactivate)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"该企业有历史已删企业，将直接启用原记录");if(deleted)db.update("update er_enterprise_profile set company_name=?,sales_manager=?,subject_type=?,source=?,monitoring_enabled=?,deleted=false,deleted_at=null,deleted_by=null,updated_at=? where unified_credit_code=?",name.trim(),sales.trim(),type==null?"ENTERPRISE":type,source,enabled==null||enabled,n,c);else db.update("update er_enterprise_profile set company_name=?,sales_manager=?,updated_at=? where unified_credit_code=?",name.trim(),sales.trim(),n,c);}else db.update("insert into er_enterprise_profile(company_name,unified_credit_code,sales_manager,subject_type,source,monitoring_enabled,collection_status,created_at,updated_at) values(?,?,?,?,?,?,'UNSCANNED',?,?)",name.trim(),c,sales.trim(),type==null?"ENTERPRISE":type,source,enabled==null||enabled,n,n);return db.queryForMap("select id,company_name \"companyName\",unified_credit_code \"unifiedCreditCode\",sales_manager \"salesManager\" from er_enterprise_profile where unified_credit_code=?",c);}
  @Transactional public void delete(long id,String actor){int changed=db.update("update er_enterprise_profile set deleted=true,deleted_at=?,deleted_by=?,updated_at=? where id=? and deleted=false",Instant.now(),actor,Instant.now(),id);if(changed==0)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");}
  public Map<String,Object> monitoring(long id,boolean enabled){int changed=db.update("update er_enterprise_profile set monitoring_enabled=?,updated_at=? where id=? and deleted=false",enabled,Instant.now(),id);if(changed==0)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");return Map.of("id",id,"monitoringEnabled",enabled);} public Map<String,Object> scan(long id){return scanQueued(id,null);}
  @Transactional public Map<String,Object> scan(long id,Long runId){Map<String,Object> p;try{p=db.queryForMap("select company_name \"companyName\",unified_credit_code \"unifiedCreditCode\",monitoring_enabled \"monitoringEnabled\" from er_enterprise_profile where id=? and deleted=false",id);}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");}if(!Boolean.TRUE.equals(p.get("monitoringEnabled")))throw new IllegalStateException("请先开启监测");Instant now=Instant.now();db.update("update er_enterprise_profile set collection_status='COLLECTING',updated_at=? where id=?",now,id);db.update("insert into er_collection_attempt(profile_id,run_id,status,attempt_no,started_at,created_at) values(?,?,'COLLECTING',coalesce((select max(attempt_no)+1 from er_collection_attempt a where a.profile_id=?),1),?,?)",id,runId,id,now,now);long attempt=db.queryForObject("select max(id) from er_collection_attempt where profile_id=?",Long.class,id);int good=0;String failure=null;for(String cap:CAPS){try{var allocation=keys.nextAllocation();var r=client.call(allocation.authorization(),cap,(String)p.get("companyName"),(String)p.get("unifiedCreditCode"));if("SUCCEEDED".equals(r.status())){keys.markSuccess(allocation.id());db.update("insert into er_capability_result(attempt_id,capability_code,status,hit,record_count,normalized_json,collected_at) values(?,?,?,?,?,?,?)",attempt,cap,r.status(),r.hit(),r.records().size(),recordsJson(r.records()),now);good++;}else{keys.markFailure(allocation.id(),r.message());failure=r.message();db.update("insert into er_capability_result(attempt_id,capability_code,status,error_code,error_message,collected_at) values(?,?,?,?,?,?)",attempt,cap,r.status(),r.status(),r.message(),now);}}catch(RuntimeException e){failure=e.getMessage();db.update("insert into er_capability_result(attempt_id,capability_code,status,error_code,error_message,collected_at) values(?,?,?,?,?,?)",attempt,cap,"FAILED","COLLECTION_ERROR",e.getMessage(),now);}}String s=good==CAPS.size()?"SUCCEEDED":good==0?"FAILED":"PARTIAL";db.update("update er_collection_attempt set status=?,finished_at=? where id=?",s,now,attempt);db.update("update er_enterprise_profile set collection_status=?,latest_success_at=case when ?<>'FAILED' then ? else latest_success_at end,latest_failure_at=case when ?='FAILED' then ? else latest_failure_at end,updated_at=? where id=?",s,s,now,s,now,now,id);if(!"FAILED".equals(s))score(id,attempt,now,"PARTIAL".equals(s));Map<String,Object>out=new LinkedHashMap<>();out.put("status",s);out.put("attemptId",attempt);out.put("completedCapabilities",good);out.put("totalCapabilities",CAPS.size());if(failure!=null)out.put("failureReason",failure);return out;}
  @Transactional public Map<String,Object> scanQueued(long id,Long runId){
    Map<String,Object> p;
    try{p=db.queryForMap("select company_name \"companyName\",unified_credit_code \"unifiedCreditCode\",monitoring_enabled \"monitoringEnabled\" from er_enterprise_profile where id=? and deleted=false",id);}
    catch(org.springframework.dao.EmptyResultDataAccessException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");}
    if(!Boolean.TRUE.equals(p.get("monitoringEnabled")))throw new IllegalStateException("请先开启监测");
    if(db.queryForObject("select count(*) from er_collection_attempt where profile_id=? and status='COLLECTING'",Integer.class,id)>0)throw new IllegalStateException("该企业已有进行中的采集任务");
    Instant now=Instant.now(); long attempt;
    List<Map<String,Object>> pending=db.queryForList("select id from er_collection_attempt where profile_id=? and status in ('PENDING_QUOTA','PARTIAL') order by id desc limit 1",id);
    if(pending.isEmpty()){
      db.update("insert into er_collection_attempt(profile_id,run_id,status,attempt_no,started_at,created_at) values(?,?,'COLLECTING',coalesce((select max(attempt_no)+1 from er_collection_attempt a where a.profile_id=?),1),?,?)",id,runId,id,now,now);
      attempt=db.queryForObject("select max(id) from er_collection_attempt where profile_id=?",Long.class,id);
    }else{
      attempt=((Number)pending.getFirst().get("id")).longValue();
      db.update("update er_collection_attempt set status='COLLECTING',run_id=?,started_at=?,finished_at=null where id=?",runId,now,attempt);
    }
    Set<String> completed=new HashSet<>(db.queryForList("select capability_code from er_capability_result where attempt_id=? and status='SUCCEEDED'",String.class,attempt));
    int good=completed.size(); String failure=null; boolean quotaPaused=false;
    for(String cap:CAPS){
      if(completed.contains(cap))continue;
      try{
        var allocation=keys.nextAllocation();
        var r=client.call(allocation.authorization(),cap,(String)p.get("companyName"),(String)p.get("unifiedCreditCode"));
        if("SUCCEEDED".equals(r.status())){keys.markSuccess(allocation.id());saveCapability(attempt,cap,r.status(),r.hit(),r.records().size(),recordsJson(r.records()),null,null,now);good++;}
        else{keys.markFailure(allocation.id(),r.message());failure=r.message();saveCapability(attempt,cap,r.status(),null,null,null,r.status(),r.message(),now);}
      }catch(KeyService.QuotaExhaustedException e){quotaPaused=true;break;}
      catch(RuntimeException e){failure=e.getMessage();saveCapability(attempt,cap,"FAILED",null,null,null,"COLLECTION_ERROR",e.getMessage(),now);}
    }
    String s=quotaPaused?"PENDING_QUOTA":good==CAPS.size()?"SUCCEEDED":good==0?"FAILED":"PARTIAL";
    if("PENDING_QUOTA".equals(s)){
      db.update("update er_collection_attempt set status='PENDING_QUOTA',finished_at=null,error_code='QUOTA_EXHAUSTED',error_message=? where id=?",new KeyService.QuotaExhaustedException().getMessage(),attempt);
      db.update("update er_enterprise_profile set collection_status='PENDING_QUOTA',updated_at=? where id=?",now,id);
    }else{
      db.update("update er_collection_attempt set status=?,finished_at=?,error_code=?,error_message=? where id=?",s,now,failure==null?null:"COLLECTION_ERROR",failure,attempt);
      if("SUCCEEDED".equals(s)){
        score(id,attempt,now,false);
        String level=db.queryForObject("select risk_level from er_enterprise_profile where id=?",String.class,id);
        int days=cadenceDays(level);
        db.update("update er_enterprise_profile set collection_status='SUCCEEDED',latest_success_at=?,next_collection_at=?,collection_interval_days=?,latest_failure_at=null,latest_failure_code=null,latest_failure_message=null,updated_at=? where id=?",now,now.plus(Duration.ofDays(days)),days,now,id);
      }else{
        if("PARTIAL".equals(s))score(id,attempt,now,true);
        db.update("update er_enterprise_profile set collection_status=?,latest_success_at=?,next_collection_at=?,latest_failure_at=?,latest_failure_code=?,latest_failure_message=?,updated_at=? where id=?",s,now,now.plus(Duration.ofHours(6)),now,failure==null?null:"COLLECTION_ERROR",failure,now,id);
      }
    }
    Map<String,Object>out=new LinkedHashMap<>();out.put("status",s);out.put("attemptId",attempt);out.put("completedCapabilities",good);out.put("totalCapabilities",CAPS.size());
    Map<String,Object>latest=db.queryForMap("select latest_success_at latestSuccessAt,next_collection_at nextCollectionAt,collection_status collectionStatus,risk_level riskLevel from er_enterprise_profile where id=?",id);
    out.put("latestSuccessAt",latest.get("latestSuccessAt"));out.put("nextCollectionAt",latest.get("nextCollectionAt"));out.put("collectionStatus",latest.get("collectionStatus"));out.put("riskLevel",latest.get("riskLevel"));
    if(failure!=null)out.put("failureReason",failure);return out;
  }
  private void saveCapability(long attempt,String cap,String status,Boolean hit,Integer count,String normalized,String errorCode,String errorMessage,Instant now){
    int exists=db.queryForObject("select count(*) from er_capability_result where attempt_id=? and capability_code=?",Integer.class,attempt,cap);
    if(exists==0)db.update("insert into er_capability_result(attempt_id,capability_code,status,hit,record_count,normalized_json,error_code,error_message,collected_at) values(?,?,?,?,?,?,?,?,?)",attempt,cap,status,hit,count,normalized,errorCode,errorMessage,now);
    else db.update("update er_capability_result set status=?,hit=?,record_count=?,normalized_json=?,error_code=?,error_message=?,collected_at=? where attempt_id=? and capability_code=?",status,hit,count,normalized,errorCode,errorMessage,now,attempt,cap);
  }
  private int cadenceDays(String level){String base=level==null?"":level.split("\\*",2)[0];return Set.of("CRITICAL","HIGH","MEDIUM").contains(base)?7:15;}
  private String recordsJson(List<Map<String,Object>> rs){StringBuilder b=new StringBuilder("{\"records\":[");for(int i=0;i<rs.size();i++){if(i>0)b.append(',');b.append('{');int j=0;for(var e:rs.get(i).entrySet()){if(j++>0)b.append(',');b.append('"').append(esc(e.getKey())).append("\":\"").append(esc(String.valueOf(e.getValue()))).append('"');}b.append('}');}return b.append("]}").toString();}private String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r");}
  private void score(long id,long attempt,Instant now,boolean provisional){String type=db.queryForObject("select subject_type from er_enterprise_profile where id=?",String.class,id);List<Map<String,Object>> fs=db.queryForList("select factor_code factorCode,factor_name factorName,risk_level riskLevel,enabled from er_risk_model_factor where model_type=? and factor_code<>'LIMIT_CONSUMPTION'",type);int[] counts=new int[4];int hitFactors=0;boolean unavailable=false;List<Map<String,Object>> factors=new ArrayList<>();for(Map<String,Object>f:fs){boolean enabled=Boolean.TRUE.equals(f.get("enabled"));String configured=String.valueOf(f.get("riskLevel"));List<Map<String,Object>>r=db.queryForList("select status,hit,record_count recordCount,error_message errorMessage from er_capability_result where attempt_id=? and capability_code=?",attempt,f.get("factorCode"));boolean ok=!r.isEmpty()&&"SUCCEEDED".equals(r.getFirst().get("status")),trigger=ok&&Boolean.TRUE.equals(r.getFirst().get("hit"));int rank=levelRank(configured);String result=!enabled?"DISABLED":!ok?"UNAVAILABLE":trigger&&rank>0?"TRIGGERED":"NOT_TRIGGERED";if("UNAVAILABLE".equals(result))unavailable=true;if("TRIGGERED".equals(result)){counts[rank-1]++;hitFactors++;}Map<String,Object>e=new LinkedHashMap<>();e.put("factorCode",f.get("factorCode"));e.put("factorName",f.get("factorName"));e.put("riskLevel",configured);e.put("configuredRiskLevel",configured);e.put("enabled",enabled);e.put("available",ok);e.put("triggered",trigger);e.put("recordCount",r.isEmpty()?0:r.getFirst().get("recordCount"));e.put("errorMessage",r.isEmpty()?null:r.getFirst().get("errorMessage"));e.put("result",result);factors.add(e);}String display=riskDisplay(counts,provisional,unavailable);Map<String,Object>evidence=new LinkedHashMap<>();evidence.put("factors",factors);evidence.put("hitFactorCount",hitFactors);evidence.put("provisional",provisional);evidence.put("compatibility",false);db.update("insert into er_risk_score(profile_id,model_type,model_version,score,risk_level,coverage,evidence_json,scored_at) values(?,?,?,?,?,?,?,?)",id,type,1,null,display,null,json(evidence),now);db.update("update er_enterprise_profile set risk_score=null,risk_level=?,coverage=null,updated_at=? where id=?",display,now,id);}public static String riskDisplay(int[] counts,boolean provisional,boolean unavailable){for(int i=counts.length-1;i>=0;i--)if(counts[i]>0)return (switch(i){case 0->"LOW";case 1->"MEDIUM";case 2->"HIGH";default->"CRITICAL";})+"*"+counts[i];return provisional&&unavailable?"INSUFFICIENT_DATA":"NONE";}private String json(Object value){try{return JSON.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("无法保存风险预警证据",e);}}private int levelRank(String level){return switch(String.valueOf(level)){case "LOW"->1;case "MEDIUM"->2;case "HIGH"->3;case "CRITICAL"->4;default->0;};}private String levelCode(int rank){return switch(rank){case 1->"LOW";case 2->"MEDIUM";case 3->"HIGH";default->"CRITICAL";};}
  @SuppressWarnings("unchecked") private Map<String,Object> parseEvidence(String value){try{return JSON.readValue(value,Map.class);}catch(Exception e){return null;}}
  private static final ObjectMapper JSON = new ObjectMapper();
  private static final Map<String,List<String>> BASIC_DETAIL_ALIASES = Map.ofEntries(
      Map.entry("企业名称", List.of("企业名称", "公司名称", "名称")),
      Map.entry("统一社会信用代码", List.of("统一社会信用代码", "社会信用代码", "统一信用代码")),
      Map.entry("登记状态", List.of("登记状态", "企业状态", "经营状态")),
      Map.entry("法定代表人", List.of("法定代表人", "法人", "法定代表人姓名")),
      Map.entry("注册资本", List.of("注册资本", "注册资金")),
      Map.entry("实缴资本", List.of("实缴资本", "实收资本")),
      Map.entry("核准日期", List.of("核准日期", "核准时间")),
      Map.entry("成立日期", List.of("成立日期", "成立时间", "注册日期")),
      Map.entry("企业类型", List.of("企业类型", "公司类型", "经济类型")),
      Map.entry("企业规模", List.of("企业规模", "人员规模", "人员规模区间", "规模")),
      Map.entry("行业", List.of("行业", "所属行业", "行业门类", "国标行业", "行业分类")),
      Map.entry("参保人数", List.of("参保人数", "社保人数", "社保缴纳人数", "员工人数")),
      Map.entry("注册地址", List.of("注册地址", "企业地址", "住所", "地址", "注册地")),
      Map.entry("城市", List.of("城市", "地市", "所在城市")),
      Map.entry("区县", List.of("区县", "区", "所在区县")),
      Map.entry("经营范围", List.of("经营范围", "业务范围")));

  public Map<String,Object> snapshot(long id){Map<String,Object>p;try{p=db.queryForMap("select id,company_name companyName,unified_credit_code unifiedCreditCode,sales_manager salesManager,latest_collection_batch_no latestCollectionBatchNo,subject_type subjectType,source,monitoring_enabled monitoringEnabled,collection_status collectionStatus,latest_success_at latestSuccessAt,risk_score riskScore,risk_level riskLevel,coverage,created_at createdAt from er_enterprise_profile where id=? and deleted=false",id);}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"企业不存在");}List<Map<String,Object>>as=db.queryForList("select id,status,attempt_no attemptNo,run_id runId,started_at startedAt,finished_at finishedAt from er_collection_attempt where profile_id=? order by id desc",id);List<Map<String,Object>>cs=as.isEmpty()?List.of():db.queryForList("select capability_code capability,status,hit,record_count recordCount,normalized_json normalized,error_code errorCode,error_message errorMessage,collected_at collectedAt from er_capability_result where attempt_id=? and capability_code<>'LIMIT_CONSUMPTION' order by id",as.getFirst().get("id"));Map<String,Object>b=new LinkedHashMap<>();for(Map<String,Object>c:cs)if("COMPANY_REGISTRATION".equals(c.get("capability"))){b=basicDetails(String.valueOf(c.get("normalized")));break;}Map<String,Object> warningEvidence=warningEvidence(id,String.valueOf(p.getOrDefault("subjectType",p.get("subjecttype"))),cs);return new LinkedHashMap<>(Map.of("profile",p,"attempts",as,"capabilities",cs,"basicDetails",b,"warningEvidence",warningEvidence));}private Map<String,Object> warningEvidence(long id,String type,List<Map<String,Object>> capabilities){try{Map<String,Object>score=db.queryForMap("select evidence_json evidenceJson,scored_at scoredAt from er_risk_score where profile_id=? order by scored_at desc limit 1",id);Map<String,Object>e=withoutLimitConsumption(JSON.readValue(String.valueOf(score.get("evidenceJson")),Map.class));e.put("scoredAt",score.get("scoredAt"));return e;}catch(Exception ignored){List<Map<String,Object>>fs=db.queryForList("select factor_code factorCode,factor_name factorName,risk_level riskLevel,enabled from er_risk_model_factor where model_type=? and factor_code<>'LIMIT_CONSUMPTION' order by factor_code",type);List<Map<String,Object>>factors=new ArrayList<>();int hits=0;for(Map<String,Object>f:fs){Map<String,Object>c=capabilities.stream().filter(x->Objects.equals(x.get("capability"),f.get("factorCode"))).findFirst().orElse(null);boolean enabled=Boolean.TRUE.equals(f.get("enabled")),available=c!=null&&"SUCCEEDED".equals(c.get("status")),triggered=available&&Boolean.TRUE.equals(c.get("hit"));String result=!enabled?"DISABLED":!available?"UNAVAILABLE":triggered?"TRIGGERED":"NOT_TRIGGERED";if(enabled&&triggered)hits++;Map<String,Object>x=new LinkedHashMap<>();x.put("factorCode",f.get("factorCode"));x.put("factorName",f.get("factorName"));x.put("riskLevel",f.get("riskLevel"));x.put("configuredRiskLevel",f.get("riskLevel"));x.put("enabled",enabled);x.put("available",available);x.put("triggered",triggered);x.put("recordCount",c==null?0:c.get("recordCount"));x.put("errorMessage",c==null?null:c.get("errorMessage"));x.put("result",result);factors.add(x);}Map<String,Object>e=new LinkedHashMap<>();e.put("factors",factors);e.put("hitFactorCount",hits);e.put("compatibility",true);return e;}}
  @SuppressWarnings("unchecked") private Map<String,Object> withoutLimitConsumption(Map<String,Object> evidence){Object raw=evidence.get("factors");if(raw instanceof List<?> list){List<Map<String,Object>>factors=new ArrayList<>();for(Object item:list)if(item instanceof Map<?,?> factor&&!"LIMIT_CONSUMPTION".equals(String.valueOf(factor.get("factorCode"))))factors.add(new LinkedHashMap<>((Map<String,Object>)factor));evidence.put("factors",factors);evidence.put("hitFactorCount",factors.stream().filter(f->"TRIGGERED".equals(String.valueOf(f.get("result")))).count());}return evidence;}
  private Map<String,Object> basicDetails(String normalized){
    Map<String,String> source=new LinkedHashMap<>();
    readStructuredDetails(normalized,source);
    for(String canonical:BASIC_DETAIL_ALIASES.keySet())for(String alias:BASIC_DETAIL_ALIASES.get(canonical)){String v=source.get(alias);if(present(v)){source.put(canonical,v);break;}}
    if(!present(source.get("注册地址"))){String address=String.join("",List.of(source.getOrDefault("省份",source.getOrDefault("省", "")),source.getOrDefault("城市",""),source.getOrDefault("区县",source.getOrDefault("区", "")),first(source,"详细地址","地址","住所")));if(present(address))source.put("注册地址",address);}
    Map<String,Object> details=new LinkedHashMap<>();
    for(String field:BASIC_DETAIL_ALIASES.keySet())if(present(source.get(field)))details.put(field,source.get(field));
    return details;
  }
  private void readStructuredDetails(String raw,Map<String,String> out){
    try{JsonNode records=JSON.readTree(raw).path("records");if(records.isArray())for(JsonNode record:records){if(record.has("字段")&&record.has("值")){put(out,record.path("字段").asText(),record.path("值").asText());}else if(record.isObject())record.fields().forEachRemaining(e->put(out,e.getKey(),e.getValue().asText()));}if(!out.isEmpty())return;}catch(Exception ignored){}
    for(String line:raw.split("\\R")){String x=line.trim();if(!x.startsWith("|")||!x.endsWith("|"))continue;String[] cells=x.substring(1,x.length()-1).split("\\|",-1);if(cells.length>=2)put(out,cells[0].trim(),cells[1].trim());}
  }
  private void put(Map<String,String> out,String key,String value){if(present(key)&&present(value)&&!"字段".equals(key)&&!"值".equals(value))out.putIfAbsent(key,value.trim());}
  private String first(Map<String,String> values,String... keys){for(String key:keys)if(present(values.get(key)))return values.get(key);return "";}
  private boolean present(String value){return value!=null&&!value.isBlank()&&!"-".equals(value)&&!"--".equals(value)&&!"null".equalsIgnoreCase(value);}
  public List<Map<String,Object>>models(){return modelRows(db.queryForList("select model_type,factor_code,factor_name,risk_level,enabled,version_no from er_risk_model_factor where factor_code<>'LIMIT_CONSUMPTION' order by model_type,factor_code"));}@Transactional public List<Map<String,Object>>saveModel(String type,List<Factor>fs){if(fs==null||fs.size()!=FACTORS.size()||fs.stream().anyMatch(f->!FACTORS.contains(f.factorCode())||f.riskLevel()==null||!Set.of("LOW","MEDIUM","HIGH","CRITICAL").contains(f.riskLevel())||(f.enabled()&&"NONE".equals(f.riskLevel()))))throw new IllegalArgumentException("必须完整配置五个风险因素且开启因素必须配置有效风险等级");for(Factor f:fs)db.update("update er_risk_model_factor set risk_level=?,enabled=?,version_no=version_no+1,updated_at=? where model_type=? and factor_code=?",f.riskLevel(),f.enabled(),Instant.now(),type.toUpperCase(Locale.ROOT),f.factorCode());return models();}private List<Map<String,Object>>modelRows(List<Map<String,Object>>rs){return rs.stream().map(r->{Map<String,Object>x=new LinkedHashMap<>();x.put("modelType",r.get("model_type"));x.put("factorCode",r.get("factor_code"));x.put("factorName",r.get("factor_name"));x.put("riskLevel",r.get("risk_level"));x.put("enabled",r.get("enabled"));x.put("versionNo",r.get("version_no"));return x;}).toList();}
}
